// vite.config.js
export default defineConfig({
  define: {
    __DEV__: JSON.stringify(false),
    __FEATURE_X__: JSON.stringify(true),
  },
})
```

```js
if (__DEV__) {
  console.log('debug') // removed in production build
}
```

Notes: values must be JSON-stringified strings (or literals) so replacement is valid JS; `import.meta.env.PROD`/`DEV` already work this way. For side-effect-free modules, ensure `"sideEffects": false` in package.json so unused imports are dropped. If the constant comes from another module, the bundler may not inline it — prefer `define` or `import.meta.env` over a runtime export.

